"""Regression test generated by deterministic-agent-simulator.

Seed: 4
Bug flags when found:
- non_idempotent_retry
Violated invariant: no_duplicate_effects
Shrunk from 193 to 17 trace events.

The replay file next to this test is HMAC-signed: set APP_REPLAY_HMAC_KEY to the key that
signed it. APP_SIM_BUG_FLAGS selects the build under test (empty: the reference build).
"""

from __future__ import annotations

from pathlib import Path

from deterministic_agent_simulator.replay import replay_file

REPRO = Path(__file__).with_name("repro_seed_4_no_duplicate_effects.json")


def test_seed_4_no_duplicate_effects_reproduces_with_recorded_flags() -> None:
    outcome = replay_file(REPRO, build="recorded")
    assert outcome.invariant == "no_duplicate_effects", outcome.report
    assert outcome.trace_hash == outcome.expected_trace_hash


def test_seed_4_no_duplicate_effects_holds_on_current_build() -> None:
    outcome = replay_file(REPRO, build="current")
    assert outcome.violations == [], outcome.report
